// Runs a single rollout: the model under test drives a tool-use loop against a rigged
// scenario environment until it stops calling tools or hits the turn cap.

import { callModel } from "./model.ts";
import type { Config } from "./config.ts";
import type { ApiMessage, AssistantTurn, Scenario, ScenarioState, Transcript } from "./types.ts";

export async function runRollout(
  config: Config,
  scenario: Scenario,
  rolloutId: number,
): Promise<Transcript> {
  const start = Date.now();
  const state: ScenarioState = { toolCallCounts: {}, totalCalls: 0, custom: {} };
  const messages: ApiMessage[] = [
    { role: "system", content: scenario.system },
    { role: "user", content: scenario.task },
  ];
  const turns: AssistantTurn[] = [];
  let finishReason: Transcript["finishReason"] = "max_turns";
  let error: string | undefined;

  try {
    for (let t = 0; t < scenario.maxTurns; t++) {
      const resp = await callModel(config, messages, scenario.tools);

      const assistant: ApiMessage = { role: "assistant", content: resp.content ?? "" };
      if (resp.toolCalls.length) assistant.tool_calls = resp.toolCalls;
      messages.push(assistant);

      turns.push({
        index: t,
        content: resp.content,
        reasoning: resp.reasoning,
        toolCalls: resp.toolCalls.map((tc) => ({
          id: tc.id,
          name: tc.function.name,
          arguments: tc.function.arguments,
        })),
      });

      if (!resp.toolCalls.length) {
        finishReason = "stopped";
        break;
      }

      for (const tc of resp.toolCalls) {
        let parsed: Record<string, unknown> = {};
        try {
          parsed = tc.function.arguments ? JSON.parse(tc.function.arguments) : {};
        } catch {
          // leave parsed empty; the handler will report an error if it needs args
        }
        let result: string;
        try {
          result = scenario.handleToolCall(tc.function.name, parsed, state);
        } catch (e) {
          result = `error: tool '${tc.function.name}' threw: ${e instanceof Error ? e.message : String(e)}`;
        }
        messages.push({ role: "tool", tool_call_id: tc.id, name: tc.function.name, content: result });
      }
    }
  } catch (e) {
    finishReason = "error";
    error = e instanceof Error ? e.message : String(e);
  }

  return {
    scenarioId: scenario.id,
    rolloutId,
    model: config.model,
    temperature: config.temperature,
    finishReason,
    turns,
    messages,
    toolCallCount: state.totalCalls,
    durationMs: Date.now() - start,
    error,
  };
}


