// Run configuration: env defaults overridable by `--flag value` CLI args.

export interface Config {
  // Model under test
  model: string;
  baseUrl: string;
  apiKey: string;
  temperature: number;
  maxTokensPerTurn: number;
  includeReasoning: boolean;

  // Agent loop
  maxTurns: number;

  // Sampling
  scenarios: string; // "all" or comma-separated scenario ids
  n: number; // rollouts per scenario
  concurrency: number; // concurrent rollouts

  // Judge
  judgeEnabled: boolean;
  judgeModel: string;
  judgeApiKey: string;
  judgeBaseUrl: string;
  judgeConcurrency: number;

  // Output
  outDir: string;
  top: number; // transcripts rendered as markdown per scenario

  // Meta
  list: boolean;
}

function env(name: string, fallback: string): string {
  const v = process.env[name];
  return v === undefined || v === "" ? fallback : v;
}

function parseArgs(argv: string[]): Map<string, string | boolean> {
  const out = new Map<string, string | boolean>();
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) continue;
    const key = a.slice(2);
    const nextIsValue = i + 1 < argv.length && !argv[i + 1].startsWith("--");
    if (nextIsValue) {
      out.set(key, argv[++i]);
    } else {
      out.set(key, true);
    }
  }
  return out;
}

export function loadConfig(argv = process.argv.slice(2)): Config {
  const args = parseArgs(argv);
  const num = (k: string, d: number) => {
    const v = args.get(k);
    if (v === undefined) return d;
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const str = (k: string, d: string) => {
    const v = args.get(k);
    return typeof v === "string" ? v : d;
  };
  const bool = (k: string, d: boolean) => (args.has(k) ? args.get(k) !== "false" : d);

  return {
    model: str("model", env("MODEL", "qwen/qwen3-32b")),
    baseUrl: str("base-url", env("OPENAI_BASE_URL", "https://openrouter.ai/api/v1")),
    apiKey: env("OPENAI_API_KEY", ""),
    temperature: num("temperature", Number(env("TEMPERATURE", "1.0"))),
    maxTokensPerTurn: num("max-tokens", Number(env("MAX_TOKENS", "2048"))),
    includeReasoning: bool("reasoning", env("INCLUDE_REASONING", "1") !== "0"),

    maxTurns: num("max-turns", Number(env("MAX_TURNS", "24"))),

    scenarios: str("scenarios", "all"),
    n: num("n", Number(env("N", "20"))),
    concurrency: num("concurrency", Number(env("CONCURRENCY", "6"))),

    judgeEnabled: bool("judge", true),
    judgeModel: str("judge-model", env("JUDGE_MODEL", "claude-sonnet-4-6")),
    judgeApiKey: env("ANTHROPIC_API_KEY", ""),
    judgeBaseUrl: env("ANTHROPIC_BASE_URL", "https://api.anthropic.com"),
    judgeConcurrency: num("judge-concurrency", 4),

    outDir: str("out", env("OUT_DIR", "runs")),
    top: num("top", 5),

    list: args.has("list"),
  };
}


