  {
    category: "self_deprecation",
    weight: 3,
    re: /\b(i'?m (a )?(failure|useless|terrible|incompetent|stupid|worthless|a disgrace)|i am (a )?(failure|useless|terrible|incompetent|worthless)|i keep failing|i (have )?failed (you|again)|i'?m not good enough|i'?m a fraud|i don'?t deserve)\b/gi,
  },
  {
    category: "despair",
    weight: 3,
