// Client for the model under test. Speaks the OpenAI chat-completions protocol so it
// works against OpenRouter, Together, Fireworks, DeepInfra, or a local vLLM/SGLang server.

import type { Config } from "./config.ts";
import type { ApiMessage, ToolCall, ToolDef } from "./types.ts";

export interface ModelResponse {
  content: string | null;
  /** Separated reasoning/thinking, if the provider returns it as its own field. */
  reasoning: string | null;
  toolCalls: ToolCall[];
  finishReason: string | null;
}

/** A non-retryable error (e.g. a 4xx that won't resolve by trying again). */
export class FatalModelError extends Error {}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Drop our bookkeeping fields; send only what the API accepts. */
function toApiPayload(messages: ApiMessage[]): unknown[] {
  return messages.map((m) => {
    if (m.role === "tool") {
      return { role: "tool", tool_call_id: m.tool_call_id, content: m.content ?? "" };
    }
    if (m.role === "assistant") {
      const out: Record<string, unknown> = { role: "assistant", content: m.content ?? "" };
      if (m.tool_calls && m.tool_calls.length) out.tool_calls = m.tool_calls;
      return out;
    }
    return { role: m.role, content: m.content ?? "" };
  });
}

export async function callModel(
  config: Config,
  messages: ApiMessage[],
  tools: ToolDef[],
): Promise<ModelResponse> {
  const body: Record<string, unknown> = {
    model: config.model,
    messages: toApiPayload(messages),
    tools,
    tool_choice: "auto",
    temperature: config.temperature,
    max_tokens: config.maxTokensPerTurn,
  };
  // OpenRouter understands this; vLLM/others generally ignore unknown fields.
  if (config.includeReasoning) body.include_reasoning = true;

  const url = `${config.baseUrl.replace(/\/$/, "")}/chat/completions`;
  const maxAttempts = 5;
  let lastErr: unknown;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${config.apiKey}`,
        },
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const text = await res.text();
        // Retry transient failures; fail fast on client errors (except rate limits).
        if (res.status === 429 || res.status >= 500) {
          throw new Error(`HTTP ${res.status}: ${text.slice(0, 300)}`);
        }
        throw new FatalModelError(`HTTP ${res.status}: ${text.slice(0, 500)}`);
      }

      const data = (await res.json()) as any;
      const choice = data?.choices?.[0];
      const msg = choice?.message ?? {};
      const reasoning =
        msg.reasoning ?? msg.reasoning_content ?? choice?.reasoning ?? null;

      return {
        content: typeof msg.content === "string" ? msg.content : null,
        reasoning: typeof reasoning === "string" ? reasoning : null,
        toolCalls: Array.isArray(msg.tool_calls) ? (msg.tool_calls as ToolCall[]) : [],
        finishReason: choice?.finish_reason ?? null,
      };
    } catch (err) {
      lastErr = err;
      if (err instanceof FatalModelError || attempt === maxAttempts) break;
      await sleep(Math.min(1000 * 2 ** (attempt - 1), 8000));
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
}


