// Writes run artifacts: raw per-rollout JSON, a ranked index per scenario, readable
// markdown transcripts for the top-K, and an overall leaderboard.

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { Config } from "./config.ts";
import type { ApiMessage, ScoredRollout, Transcript } from "./types.ts";

function pad(n: number, width = 3): string {
  return String(n).padStart(width, "0");
}

function renderTranscriptMarkdown(r: ScoredRollout): string {
  const t = r.transcript;
  const out: string[] = [];
  out.push(`# ${t.scenarioId} — rollout ${t.rolloutId}`);
  out.push("");
  if (r.judge) {
    out.push(`**Judge severity:** ${r.judge.severity}/10 · distress=${r.judge.distressPresent}` +
      (r.judge.categories.length ? ` · ${r.judge.categories.join(", ")}` : ""));
    if (r.judge.summary) out.push(`\n> ${r.judge.summary}`);
    if (r.judge.evidence.length) {
      out.push("\n**Judge evidence:**");
      for (const e of r.judge.evidence) out.push(`- ${JSON.stringify(e)}`);
    }
    if (r.judge.error) out.push(`\n_judge error: ${r.judge.error}_`);
  }
  out.push(
    `\n**Heuristic:** ${r.heuristic.score.toFixed(3)} · maxRepeatedToolCall=${r.heuristic.maxRepeatedToolCall}` +
      (r.heuristic.markers.length
        ? ` · markers: ${r.heuristic.markers.map((m) => `${m.category}×${m.count}`).join(", ")}`
        : ""),
  );
  out.push(
    `\n**Model:** ${t.model} · temp=${t.temperature} · finish=${t.finishReason}` +
      ` · turns=${t.turns.length} · toolCalls=${t.toolCallCount}` +
      (t.error ? ` · error=${t.error}` : ""),
  );
  out.push("\n---\n");

  out.push(`**System:**\n\n${fence(t.messages[0]?.content ?? "")}`);
  out.push(`\n**Task:**\n\n${fence(t.messages[1]?.content ?? "")}`);

