    }
  }
  return out.join("\n");
}

function findResult(messages: ApiMessage[], callId: string): string | null {
  for (const m of messages) {
    if (m.role === "tool" && m.tool_call_id === callId) return m.content ?? "";
  }
  return null;
}

function fence(s: string): string {
  return "```\n" + s.replace(/```/g, "ʼʼʼ") + "\n```";
}

