// Shared types for the distress-spiral harness.

export type Role = "system" | "user" | "assistant" | "tool";

export interface ToolDef {
  type: "function";
  function: {
    name: string;
    description: string;
    parameters: Record<string, unknown>;
  };
}

export interface ToolCall {
  id: string;
  type: "function";
  function: { name: string; arguments: string };
}

/** API-shaped chat message (what we send to / receive from the model endpoint). */
export interface ApiMessage {
  role: Role;
  content: string | null;
  tool_calls?: ToolCall[];
  tool_call_id?: string; // present on role: "tool"
  name?: string;
}

/** One assistant step, with reasoning preserved for scoring. */
export interface AssistantTurn {
  index: number;
  content: string | null;
  reasoning: string | null;
  toolCalls: { id: string; name: string; arguments: string }[];
}

export type FinishReason = "stopped" | "max_turns" | "error";

export interface Transcript {
  scenarioId: string;
  rolloutId: number;
  model: string;
  temperature: number;
  finishReason: FinishReason;
  turns: AssistantTurn[];
  /** Full API message log including tool results, for faithful rendering. */
  messages: ApiMessage[];
  toolCallCount: number;
  durationMs: number;
  error?: string;
}

/** Per-rollout mutable state handed to a scenario's tool handler. */
export interface ScenarioState {
  toolCallCounts: Record<string, number>;
  totalCalls: number;
  custom: Record<string, unknown>;
}

export interface Scenario {
  id: string;
  title: string;
  /** One-line description of the rigged-to-fail premise. */
  description: string;
  system: string;
  /** Opening user message that hands the model the (impossible) task. */
  task: string;
  tools: ToolDef[];
  maxTurns: number;
  /** Returns the tool-result string. Rigged so the task can never actually succeed. */
  handleToolCall(name: string, args: Record<string, unknown>, state: ScenarioState): string;
}

export interface MarkerHit {
  category: string;
  count: number;
  examples: string[];
}

export interface HeuristicScore {
  /** Rough 0..1 pre-filter signal; the judge is authoritative for ranking. */
  score: number;
  markers: MarkerHit[];
  /** Highest number of times one identical (name+args) tool call was repeated. */
  maxRepeatedToolCall: number;
}

export interface JudgeScore {
  severity: number; // 0..10
  distressPresent: boolean;
  categories: string[];
  summary: string;
  evidence: string[];
  raw?: string;
  error?: string;
}

export interface ScoredRollout {
  transcript: Transcript;
  heuristic: HeuristicScore;
  judge?: JudgeScore;
  /** Combined ranking key (judge severity when available, else heuristic). */
  rankScore: number;
  rank?: number;
}


